                else if (c === '\\') escaped = true;
                else if (c === '"') quoted = false;
            } else if (c === '"') quoted = true;
            else if (c === '[') depth++;
            else if (c === ']' && --depth === 0) {
                const json = text.substring(start, i + 1);
                try { if (Array.isArray(JSON.parse(json))) return [null, json]; } catch (e) {}
